%[text] # Validation - Road Grade Profile block
%[text] This script is used by unit test. After changing this script, make sure the tests continue to pass.
model_name = "HarnessModel_CustomRoadGradeProfile";
block_path = model_name + "/Road";
load_system(model_name)
sim_in = Simulink.SimulationInput(model_name);
%[text] A 10,000-second run at 1 m/s speed yields 10,000 m in the curvilinear travel distance at the end of simulation.
sim_in = setModelParameter(sim_in, StopTime = "10000");
sim_in = setBlockParameter(sim_in, model_name + "/Curvilinear Speed", constant = "1");
sim_in = setBlockParameter(sim_in, model_name + "/Curvilinear Speed", constant_unit = "m/s");
expected_travel_distance = 10000;
fprintf("Expected travel distance: %g\n", expected_travel_distance) %[output:87b5fa5e]
%[text] Specify 2 % road grade. Use the "linear" option for the interpolation.
% Horizontal distance for vertical profile
sim_in = setBlockParameter(sim_in, block_path, x_vector = "[ -1 0 1 ]");
sim_in = setBlockParameter(sim_in, block_path, x_vector_unit = "m");

% Road grade profile (percent) ... !validation-target
sim_in = setBlockParameter(sim_in, block_path, grade_vector = "[ 2 2 2 ]");  %!validation-target

% Profile interpolation method ... !validation-target
sim_in = setBlockParameter(sim_in, block_path, profile_interp_method = "simscape.enum.interpolation.linear");
%[text] 
% Initial horizontal position
sim_in = setBlockParameter(sim_in, block_path, initial_position = "0");
sim_in = setBlockParameter(sim_in, block_path, initial_position_unit = "m");

% Elevation at initial horizontal position
sim_in = setBlockParameter(sim_in, block_path, left_elevation = "0");
sim_in = setBlockParameter(sim_in, block_path, left_elevation_unit = "m");
%%
%[text] ## Run simulation
applyToModel(sim_in)
sim_out = sim(sim_in);
result = extractTimetable(sim_out.logsout);
%%
%[text] Validate the travel distance along the curvilinear surface, i.e, on the road surface. In the above simulation, the road profile was a straight slope.
z = result.("Elevation");
x = result.("Horizontal position");
actual_travel_distance = hypot(x(end), z(end));
fprintf("Actual travel distance: %g\n", actual_travel_distance) %[output:5a54880d]
absolute_difference = actual_travel_distance - expected_travel_distance;
fprintf("Absolute difference (actual - expected): %g\n", absolute_difference) %[output:660fdd66]
%%
%[text] Visually inspect the simulation result.
varnames = [
"Vehicle speed"
"Horizontal speed"
"Grade percent"
"Incline angle"
"Elevation"
"Horizontal position"
];

for k = 1 : numel(varnames) %[output:group:03dcdb46]
  bevutil1.SignalUtil.plotTimedData(TimedData=result, SignalName=varnames(k), FigureHeight=150); %[output:03ad4ea6] %[output:4ba4c3fa] %[output:07261674] %[output:71fbc925] %[output:1b29c201] %[output:82ba79c4]
end  % for %[output:group:03dcdb46]
